 "content": "from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=y+dy,x+dx
            if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
              seen.add((a,b)); q.append((a,b))
        comps.append((col,comp))
    # The smallest component of the repeated object color is the marked one.
    counts={}
    for col,comp in comps: counts[col]=counts.get(col,0)+1
    candidates=[(len(comp),col,comp) for col,comp in comps if counts[col]>1]
    _,col,comp=min(candidates)
    out=[row[:] for row in grid]
    for r,c in comp: out[r][c]=0
    return out
