def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
                        seen.add((a,b)); stack.append((a,b))
            comps.append((col,cells))
    counts=Counter(col for col,cells in comps)
    # Find the color represented by the greatest number of disconnected objects;
    # recolor its smallest object to 0.
    color=max(counts, key=lambda x: counts[x])
    target=min((cells for col,cells in comps if col==color), key=len)
    out=[row[:] for row in grid]
    for r,c in target: out[r][c]=0
    return out
